do $t$
declare r text := ''; x jsonb; lg text;
begin
  r := r || 'now=' || public.ten216_collector_check(now());
  r := r || ' | +3h(no hb, limit120)=' || public.ten216_collector_check(now() + interval '3 hours');
  r := r || ' | +3h10m=' || public.ten216_collector_check(now() + interval '190 minutes');
  r := r || ' | 10 Dec with the alert open (expect off-season, NOT recovered)=' || public.ten216_collector_check('2026-12-10T12:00:00Z'::timestamptz);
  r := r || ' | alert still open=' || (select is_open::text from public.ten216_watch_alerts where condition='collector_stale');
  insert into public.ten216_test_polls (poll_id, observed_at, ok) values ('selftest', now(), true);
  r := r || ' | hb now, +70m(limit60)=' || public.ten216_collector_check(now() + interval '70 minutes');
  r := r || ' | hb now, +30m=' || public.ten216_collector_check(now() + interval '30 minutes');
  select string_agg(kind || ':' || coalesce(channel,'-') || ':' || delivered, ', ' order by id) into lg from public.ten216_watch_log;
  r := r || ' | log=' || coalesce(lg, 'none');
  select public.chart_apitennis_series(array['12166088'], '2026-09-26T03:55:00Z') into x;
  r := r || ' | rpc down after hb=' || (x->'down')::text || ' last_ok=' || (x->>'last_ok_poll_at');
  raise exception 'SELFTEST (rolled back) %', r;
end $t$
